.blog-layout {
  display: grid;
  grid-template-columns: 1fr min(65ch, 100%) 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
}

.blog-content {
  grid-column: 2;
  padding: 2rem;
}

@media (max-width: 768px) {
  .blog-content {
    padding: 1rem;
  }
}
```

## TypeScript Example

```typescript
interface BlogPost {
  id: string;
  title: string;
  content: string;
  publishedAt: Date;
  tags: string[];
}

class BlogManager {
  private posts: BlogPost[] = [];

  addPost(post: Omit<BlogPost, 'id'>): BlogPost {
    const newPost: BlogPost = {
      ...post,
      id: crypto.randomUUID(),
    };

    this.posts.push(newPost);
    return newPost;
  }

  getPostsByTag(tag: string): BlogPost[] {
    return this.posts.filter(post => 
      post.tags.includes(tag)
    );
  }
}
```

Isn't the syntax highlighting beautiful? The code blocks are now properly styled with themes that adapt to light and dark modes!

